const CSV = "id,deliverable,owner,due_date,status,actual_date,notes\r\nD01,Site possession and hoarding,KHB,2027-01-04,Complete,2027-01-04,\r\nD02,Phasing plan (Hub open during works),KHB,2027-02-01,Submitted,2027-02-01,Under Council review\r\nD03,Baseline programme,KHB,2027-02-15,Submitted,24/02/2027,Late\r\nD04,Design stage 2 report,KHB,2027-03-15,Overdue,,\r\nD05,Condition survey — M&E,KHB,2027-02-28,Complete,2027-03-02,\r\nD06,Hazardous materials survey,KHB,,Not started,,Not in original scope\r\nD07,Temporary access plan (lifts),KHB,2027-03-31,Overdue,,\r\nD08,NRF monthly progress report — Jan,Council PM,2027-02-12,Submitted,2027-02-12,\r\nD09,NRF monthly progress report — Feb,Council PM,2027-03-12,Submitted,2027-03-16,Late\r\nD10,NRF monthly progress report — Mar,Council PM,14/04/2027,Not started,,\r\nD11,NRF Tranche 1 claim,Finance,2027-03-31,Submitted,2027-03-19,\r\nD12,Active ageing operator appointment,Council PM,2027-03-31,Overdue,,EOI extended to 30 Apr\r\nD13,Childcare operator agreement signed,Legal,2027-06-30,In progress,,\r\nD14,Active ageing operator agreement signed,,2027-06-30,Not started,,Owner not assigned\r\nD15,Resident consultation summary,Community Engagement,2027-03-11,Overdue,,Postponed twice\r\nD16,Design stage 3 (detailed) report,KHB,2027-06-30,Not started,,\r\nD17,Lift package award,KHB,2027-05-15,Not started,,\r\nD18,Sports hall closure notice to users,Council PM,2027-07-31,Not started,,Depends on closure decision\r\nD19,Kitchen exhaust permit application,KHB,2027-04-30,In progress,,\r\nD20,Roof structural assessment,KHB,2027-04-15,Submitted,,Submitted — no date recorded\r\nD21,Childcare floor handover for fit-out,KHB,2028-06-30,Not started,,Programme shows Aug 2028\r\nD22,Practical completion,KHB,2028-10-31,Not started,,Programme shows 31 Dec 2028\r\n";
function parseCsv(t){const rows=[];let row=[],f='',q=false;t=t.replace(/^﻿/,'');for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++;}else q=false;}else f+=c;}else if(c==='"')q=true;else if(c===','){row.push(f);f='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(f);f='';if(row.length>1||row[0]!=='')rows.push(row);row=[];}else f+=c;}if(f!==''||row.length){row.push(f);rows.push(row);}const h=rows.shift();return rows.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]??''])));}
const SCENARIO = {id: 'WI-01', title: 'Active-ageing operator appointment slips', deliverable: 'D12', slip_weeks: 6};
const SUCCESSORS = {D12: ['D14']};            // assumption: operator agreement cannot be signed before the operator is appointed
const T2_GATES = ['D13', 'D14'];              // grant letter 2: T2 needs signed operator agreements for ALL social-service spaces
const GRANT_MAX_M = 10.2, T2_SHARE = 0.30;    // grant letter 1.2 and 2
const rows = parseCsv(CSV); const by = Object.fromEntries(rows.map(r => [r.id, r]));
const iso = d => /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : null;
const addDays = (d, n) => { const x = new Date(d + 'T00:00:00Z'); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };
const days = SCENARIO.slip_weeks * 7;
const impacts = [];
const shifted = new Set([SCENARIO.deliverable, ...(SUCCESSORS[SCENARIO.deliverable] || [])]);
for (const id of shifted) { const r = by[id]; const b = iso(r.due_date); if (!b) continue; impacts.push({item: id + ' ' + r.deliverable, baseline_due: b, scenario_due: addDays(b, days), delta_days: days}); }
const gateBase = T2_GATES.map(id => iso(by[id].due_date)).sort().pop();
const gateScen = T2_GATES.map(id => shifted.has(id) ? addDays(iso(by[id].due_date), days) : iso(by[id].due_date)).sort().pop();
const result = {scenario: SCENARIO, assumptions: [
  'Every successor of the slipped item moves by the same number of days (no float assumed).',
  'Operator agreement D14 cannot be signed before the operator appointment D12 is complete.',
  'T2 release needs both D13 and D14 signed (grant letter, section 2); the structural and M&E rough-in condition is not modelled.',
  'Dates are the planned due dates in 03_Contract_deliverables_schedule.csv, not forecasts.'],
  impacts, linked_work_items: [...shifted, 'D13'],
  grant: {tranche: 'T2', share_of_grant_pct: T2_SHARE * 100, amount_s$m: Math.round(GRANT_MAX_M * T2_SHARE * 100) / 100, basis: 'maximum grant S$10.2m x 30%; actual eligible cost may be lower',
    gate_baseline: gateBase, gate_scenario: gateScen, delay_days: Math.round((Date.parse(gateScen) - Date.parse(gateBase)) / 86400000)},
  cost_impact: 'NOT_FOUND: no cost data for operator delay was supplied; no figure is estimated',
  linked_risks: [{id: 'R06', text: by.D12 ? 'Active ageing operator not found' : '', note: 'Stored score 6 is a multiplication error (2x4=8); re-rating needs human review'}, {id: 'R01', text: 'Grant conditions reduce eligible cost', note: 'T2 timing depends on this scenario'}],
  not_assessed: ['Effect on practical completion D22 and the 22-month construction period', 'Cost of delay', 'Whether the Fund would extend or vary T2 conditions']};
return [{json: {whatif: result, whatif_json: JSON.stringify(result)}}];

